func newRetrieveCommand(opts Options, use string, mode retrievalMode, short string) *cobra.Command {
	var selection querySelection
	var jsonOut bool
	var format string
	var limit int
	var branch string
	var patterns, includeAbstract, noGlobal bool
	var source, after, before, session, agent string
	var concepts []string
	var recency bool
	var recencyHalfLife string
	cmd := &cobra.Command{
		Use:   use + " <query>",
		Short: short,
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			wantJSON, err := outputWantsJSON(jsonOut, format)
			if err != nil {
				return err
			}
			ropts, err := buildRetrievalOptions(source, after, before, session, agent, branch, concepts)
			if err != nil {
				return fmt.Errorf("--%s", err.Error())
			}
			ropts.IncludeAbstract = includeAbstract
			ropts.NoGlobalFacts = noGlobal
			ropts, err = withRecencyOptions(ropts, recency, recencyHalfLife)
			if err != nil {
				return err
			}
			selectedMode, err := selection.mode(mode)
			if err != nil {
				return err
			}
			warnRemovedSemanticAlias(cmd, use, selection.semantic)
			return runRetrieve(cmd.Context(), cmd, opts, args[0], selectedMode, limit, branch, ropts, wantJSON, patterns, use)
		},
	}
